set-payload.value:
#[if (isEmpty(payload)) {
            connected: false,
            grantedScope: null
        } else {
            connected: payload[0].status == 'CONNECTED',
            account: payload[0].external_account,
            grantedScope: payload[0].granted_scope,
            watchExpiration: payload[0].watch_expiration,
            lastSyncAt: payload[0].last_sync_at,
            lastSyncStatus: payload[0].last_sync_status
        }]

#[{
            api: 'UP',
            database: vars.databaseStatus,
            gmail: if (payload.connected) 'CONNECTED' else 'DISCONNECTED',
            whatsapp: if (isEmpty(p('whatsapp.accessToken')) or isEmpty(p('whatsapp.phoneNumberId'))) 'NOT_CONFIGURED' else 'CONFIGURED'
        }]
